\begin{align*} \tan \theta &= \frac{-1 - 4 \sqrt{3}}{4 - \sqrt{3}} \\ &= \frac{-(1 + 4 \sqrt{3})}{4 - \sqrt{3}} \\ &= \frac{-(4 + 4 \sqrt{3} + 1)}{4 - \sqrt{3}} \\ &= \frac{-5 - 4 \sqrt{3}}{4 - \sqrt{3}} \\ &= \frac{(-5 - 4 \sqrt{3})(4 + \sqrt{3})}{(4 - \sqrt{3})(4 + \sqrt{3})} \\ &= \frac{-20 - 5 \sqrt{3} - 16 \sqrt{3} - 12}{16 - 3} \\ &= \frac{-32 - 21 \sqrt{3}}{13}. \end{align*}
